def limpiar_correos(apps, schema_editor):
    """Antes de volver único el correo: vacío → nulo, todo en minúsculas y, si dos cuentas
    comparten correo, la más antigua lo conserva y a las demás se les quita (siguen entrando con
    su teléfono o cédula)."""
    User = apps.get_model("user_activity", "User")
    vistos = set()
    for u in User.objects.order_by("created_at", "id"):
        email = (u.email or "").strip().lower() or None
        if email and email in vistos:
            email = None
        if email:
            vistos.add(email)
        if email != u.email:
            User.objects.filter(pk=u.pk).update(email=email)


